import { saveUserFeedback, footerPhoneSubs } from '@utils/api.js'
export class CommentForm {
    constructor({el}) {
        this.DOM = {
            el: $(el),
            clas: el,
        }
        this.init()
    }

    checkData() {
        let flag = false
        $(`${this.DOM.clas} .error`).hide()

        // 评论
        $(`${this.DOM.clas} #comment`).removeClass('form-error')
        const comment = $(`${this.DOM.clas} #comment`).val()
        if (comment.trim().length == 0) {
            flag = true
            $(`${this.DOM.clas} .comment-error`).show()
            $(`${this.DOM.clas} #comment`).addClass('form-error')
        }

        const $customerEmail = $(`${this.DOM.clas} #email`)

        if ($customerEmail.val().trim() !== '') {
            $(`${this.DOM.clas} #checkbox-label`).removeClass('form-error')
            const subscribe = $(`${this.DOM.clas} #subscribe`).is(":checked");
            if(!subscribe) {
                flag = true
                $(`${this.DOM.clas} .subscribe-error`).show()
                $(`${this.DOM.clas} #checkbox-label`).addClass('form-error')
            }
        }


        return flag
    }

    onEvent() {
        const that = this
        $(`${that.DOM.clas} .form-textarea`).bind('input propertychange',function() {
            $(`${that.DOM.clas} .now-number`).text($(this).val().length)
        })

        $(`${that.DOM.clas} .choose`).click(function() {

            $(`${that.DOM.clas} .list`).addClass('data-show')
            const id=$(this).data('id')
            if (id) {
                $(`${that.DOM.clas} .item[data-id="${id}"]`).addClass('selected')
            }
        })

        $(`${that.DOM.clas}`).on('click', '.item', function() {
            $(this).addClass('selected')
            const id = $(this).data('id')
            $(this).siblings().removeClass('selected')
            $(`${that.DOM.clas} .choose`).addClass('has-choosed').text($(this).text()).attr('data-id', id)
            $(`${that.DOM.clas} .choose`).data('id', id)
            $(`${that.DOM.clas} .list`).removeClass('data-show')
            $('#question').removeClass('form-error')
            $('.question-error').hide()
        })

        $(document).click(function(event) {
            const select = $(`${that.DOM.clas} .select`)
            if (!select.is(event.target) && select.has(event.target).length === 0) {
                $(`${that.DOM.clas} .list`).removeClass('data-show')
            }
        })

        const customerEmail = $(`${this.DOM.clas} #email`)
        const checkboxLabel  = $(`${this.DOM.clas} #checkbox-label`)
        const customerEmailValue = this.DOM.el.data('customer-email')
        if(customerEmailValue){
            customerEmail.val(customerEmailValue)
        }

        // 初始判断（防止刷新后已填有值）
        if (customerEmail.val().trim() !== '') {
            checkboxLabel.show();
        } else {
            checkboxLabel.hide();
        }

        // 监听输入框变化
        customerEmail.on('input', function () {
            if ($(this).val().trim() !== '') {
                checkboxLabel.show();
            } else {
                checkboxLabel.hide();
                $(`${that.DOM.clas} #subscribe`).prop("checked", false);
            }
        });

        // 数据提交
        $('.submit-button').on('click',async function(e) {
            e.preventDefault()
            const flag = that.checkData()
            if(!flag) {
                const successful = that.DOM.el.data('successful')
                const query = {
                    shopifyShopId: window?.pageInfo?.shopId,
                    email: $(`${that.DOM.clas} #email`).val().trim(),
                    sourcePage: window.location.href,
                    cusContactFlag: 0,
                    subscribeFlag: $(`${that.DOM.clas} #subscribe`).is(":checked") ? 1 : 0,
                    questionType: $(`${that.DOM.clas} #question`).data('id'),
                    questionContent: $(`${that.DOM.clas} #comment`).val().trim()
                }
                try {
                    await saveUserFeedback(query)
                    pushSuccessMessage(successful)
                    $(`${that.DOM.clas} #comment`).val('')
                    $(`${that.DOM.clas} .now-number`).text('0')
                    if (!query.email) return false
                    const subscribeParams = {
                        tags: 'BCform-Subscribe',
                        email: query.email
                    }
                    await footerPhoneSubs(subscribeParams)
                } catch (error) {
                    pushErrorMessage(error.message)
                }

            }
        })
    }
    init() {
        this.onEvent()
    }
}
