export class MemberShip {
    constructor() {
        this.init()
    }
    onEvent() {
        $('.jky-12th-join-in').on('click', function() {
            window?.jackeryLoginApp.modalLogin({
                register_act: 'Activity-register',
                return_url: window.location.href
            })
        })
    }
   
    init() {
        this.onEvent()
    }
}