export class RegistrationBenefits {
    constructor() {
        this.init()
    }

    onEvent() {

        const $pcTooltips = $(".benefits-collection-registration-benefits .pc-list .info-wrap");
        const $mbInfoWrap = $(".benefits-collection-registration-benefits .mobile-list .info-wrap");

        const setArrowPosition = ($this) => {
            const $arrow = $this.find(".arrow");
            const arrowLeftPos = parseFloat($this.find("svg").css("margin-left"));
            const arrowTopPos = parseFloat($arrow.css("height"));
            $arrow.css("left", `${arrowLeftPos}px`);
            $arrow.css("top", `-${arrowTopPos}px`);
        }

        const setTooltipTop = ($this) => {
            const $arrow = $this.find(".arrow");
            const arrowHeight = parseFloat($arrow.css("border-top").split("px")[0]);
            const [, tooltipHeight] = getTooltipSize($this);
            $this.find(".tooltip-container").css("top", `-${tooltipHeight + arrowHeight}px`);
        }

        const getTooltipSize = ($this) => {
            const $tooltip = $this.find(".tooltip-container");
            const tooltipWidth = parseFloat($tooltip.css("width"));
            const tooltipHeight = parseFloat($tooltip.css("height"));
            return [tooltipWidth, tooltipHeight]
        }

        const getMargin = ($this) => {
            return (window.innerWidth - parseFloat($this.closest(".section-container-lg").css("width"))) / 2;
        }

        $pcTooltips.each(function () {
            const $this = $(this);
            setArrowPosition($this);

            const containerMargin = getMargin($this);
            const thisPosLeft = $this.offset().left;

            const [tooltipWidth] = getTooltipSize($this);
            const leftRest = thisPosLeft - containerMargin;
            const rightRest = window.innerWidth - thisPosLeft - containerMargin;

            const $tooltip = $this.find(".tooltip-container");
            const tooltipHalfWidth = tooltipWidth / 2;
            if (leftRest > tooltipHalfWidth && rightRest > tooltipHalfWidth) {
                $tooltip.css("left", `-${tooltipHalfWidth}px`);
            }

            if (rightRest < tooltipHalfWidth) {
                $tooltip.css("left", `-${tooltipWidth - rightRest + 20}px`);
            }

            setTooltipTop($this);
        });

        $mbInfoWrap.each(function () {
            const $this = $(this);

            setArrowPosition($this);

            const containerMargin = getMargin($this);
            const $thisLeftPos = $this.offset().left
            const tooltipRest = window.innerWidth - $thisLeftPos - containerMargin;

            const [tooltipWidth] = getTooltipSize($this);

            const $tooltip = $this.find(".tooltip-container");
            $tooltip.css("left", `-${tooltipWidth - tooltipRest}px`);

            setTooltipTop($this);
        });

        const tooltipShow = ($target) => {
            const position = $(".benefits-collection-registration-benefits .bc-title").text();
            window.dataLayer.push({event_parameters: null});
            window.dataLayer.push({
                event: "ga4Event",
                event_name: "promo_collection_user_clicks",
                event_parameters: {
                    current_page: window.location.href,
                    module: "LoginSection",
                    button_name: "InformationMark",
                    position: position
                }
            });
            $target.addClass('show');
        }

        if (Jackery.Utils.isLessThan1024Screen()) {

            $(document).on("touchstart", ".benefits-collection-registration-benefits .info-wrap .info", function (e) {
                e.stopPropagation();
                const $infoWrap = $(this).parent();
                if ($infoWrap.hasClass('show')) {
                    $infoWrap.removeClass('show');
                } else {
                    $mbInfoWrap.removeClass("show");
                    tooltipShow($infoWrap);
                }
            });

            $(document).on("touchstart", ".benefits-collection-registration-benefits .info-wrap .tooltip-container", function (e) {
                e.stopPropagation();
            });

            $(document).on("touchstart", function (e) {
                $mbInfoWrap.removeClass("show");
            });
        } else {

            $(document).on("mouseenter", ".benefits-collection-registration-benefits .info-wrap .info", function (e) {
                tooltipShow($(this).parent());
            });

            $(document).on("mouseleave", ".benefits-collection-registration-benefits .info-wrap .info", function (e) {
                // If the mouse is moving to the tooltip, do not close the info
                if ($(e.relatedTarget).hasClass('tooltip-container') || $(e.relatedTarget).hasClass('arrow')) {
                    return;
                }
                $(this).parent().removeClass('show');
            });

            $(document).on("mouseleave", ".benefits-collection-registration-benefits .info-wrap .tooltip-container", function (e) {
                $(this).parent().removeClass('show');
            });
        }

        $(document).on("click", ".benefits-collection-registration-benefits button", function (e) {
            const anchor = $(this).closest(".benefits-collection-registration-benefits").attr("anchor-target");
            const url = new URL(location.href);
            url.searchParams.set("hash", anchor);
            window.jackeryLoginApp && window.jackeryLoginApp.modalLogin({
                return_url: url.toString(),
                "register_act": "Account-Register"
            });
        });

    }

    init() {
        this.onEvent()
    }
}
